  const imageData = [{"article": "1-01-creating-your-first-course.md", "filename": "accessing-thrive-apprentice_step2.png", "b64": "", "alt": "Accessing Thrive Apprentice - Thrive Dashboard in Thrive Apprentice"}, {"article": "1-01-creating-your-first-course.md", "filename": "accessing-thrive-apprentice_step3.png", "b64": "", "alt": "Accessing Thrive Apprentice - Thrive Apprentice in Thrive Apprentice"}, {"article": "1-01-creating-your-first-course.md", "filename": "creating-your-first-course_step1.png", "b64": "", "alt": "Creating Your First Course - Courses in Thrive Apprentice"}, {"article": "1-01-creating-your-first-course.md", "filename": "creating-your-first-course_step2.png", "b64": "", "alt": "Creating Your First Course - Add Course in Thrive Apprentice"}, {"article": "1-01-creating-your-first-course.md", "filename": "creating-your-first-course_step3.png", "b64": "", "alt": "Creating Your First Course - Course Title in Thrive Apprentice"}, {"article": "1-01-creating-your-first-course.md", "filename": "creating-your-first-course_step4.png", "b64": "", "alt": "Creating Your First Course - Course Description in Thrive Apprentice"}, {"article": "1-01-creating-your-first-course.md", "filename": "creating-your-first-course_step5.png", "b64": "", "alt": "Creating Your First Course - Save in Thrive Apprentice"}, {"article": "1-01-creating-your-first-course.md", "filename": "adding-modules-and-chapters_step1.png", "b64": "", "alt": "Adding Modules and Chapters - Courses in Thrive Apprentice"}, {"article": "1-01-creating-your-first-course.md", "filename": "adding-modules-and-chapters_step2.png", "b64": "", "alt": "Adding Modules and Chapters - Add Module in Thrive Apprentice"}, {"article": "1-01-creating-your-first-course.md", "filename": "adding-modules-and-chapters_step3.png", "b64": "", "alt": "Adding Modules and Chapters - Module Title in Thrive Apprentice"}, {"article": "1-01-creating-your-first-course.md", "filename": "adding-modules-and-chapters_step4.png", "b64": "", "alt": "Adding Modules and Chapters - Add Chapter in Thrive Apprentice"}, {"article": "1-01-creating-your-first-course.md", "filename": "adding-your-first-lesson_step1.png", "b64": "", "alt": "Adding Your First Lesson - Add Lesson in Thrive Apprentice"}, {"article": "1-01-creating-your-first-course.md", "filename": "publishing-your-course_step1.png", "b64": "", "alt": "Publishing Your Course - Courses in Thrive Apprentice"}, {"article": "1-01-creating-your-first-course.md", "filename": "publishing-your-course_step3.png", "b64": "", "alt": "Publishing Your Course - Course Status in Thrive Apprentice"}, {"article": "1-01-creating-your-first-course.md", "filename": "publishing-your-course_step4.png", "b64": "", "alt": "Publishing Your Course - Save in Thrive Apprentice"}, {"article": "2-01-settings-guide.md", "filename": "auto-login_step1.png", "b64": "", "alt": "Auto-Login - General in Thrive Apprentice"}, {"article": "2-01-settings-guide.md", "filename": "auto-login_step2.png", "b64": "", "alt": "Auto-Login - Automatic Login in Thrive Apprentice"}, {"article": "2-01-settings-guide.md", "filename": "course-comments_step1.png", "b64": "", "alt": "Course Comments - Enable Comments for Courses in Thrive Apprentice"}, {"article": "2-01-settings-guide.md", "filename": "course-comments_step2.png", "b64": "", "alt": "Course Comments - On in Thrive Apprentice"}, {"article": "2-01-settings-guide.md", "filename": "where-to-find-dynamic-labels_step1.png", "b64": "", "alt": "Where to Find Dynamic Labels - Settings in Thrive Apprentice"}, {"article": "2-01-settings-guide.md", "filename": "where-to-find-dynamic-labels_step2.png", "b64": "", "alt": "Where to Find Dynamic Labels - Access Restrictions in Thrive Apprentice"}];

